 14	const maxBodyBytes = 1 << 20
 15	
 16	func (s *Server) createPayment(w http.ResponseWriter, r *http.Request) {
 17		fp, err := bodyFingerprint(r)
 18		if err != nil {
 19			writeError(w, err)
 20			return
 21		}
 22		var req createPaymentRequest
 23		if err := decodeJSON(r, &req); err != nil {
 24			writeError(w, err)
 25			return
 26		}
 27		amount, err := money.Parse(req.Amount, req.Currency)
 28		if err != nil {
 29			writeError(w, fmt.Errorf("amount: %w", err))
 30			return
 31		}
 32		in := payment.CreateInput{MerchantID: req.MerchantID, Amount: amount}
 33		s.idempotent(w, r, fp, func() (int, any) {
 34			p, err := s.svc.Create(r.Context(), in)
 35			if err != nil {
 36				return errorResponse(err)
 37			}
 38			return http.StatusCreated, toPaymentResponse(p)
 39		})
 40	}
 41	
 42	func (s *Server) getPayment(w http.ResponseWriter, r *http.Request) {
 43		p, err := s.svc.Get(r.Context(), r.PathValue("id"))
 44		if err != nil {
 45			writeError(w, err)
 46			return
 47		}
 48		writeJSON(w, http.StatusOK, toPaymentResponse(p))
 49	}
 50	
 51	func (s *Server) authorizePayment(w http.ResponseWriter, r *http.Request) {
 52		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Authorize(r.Context(), r.PathValue("id")) })
 53	}
 54	
 55	func (s *Server) capturePayment(w http.ResponseWriter, r *http.Request) {
 56		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Capture(r.Context(), r.PathValue("id")) })
 57	}
 58	
 59	func (s *Server) declinePayment(w http.ResponseWriter, r *http.Request) {
 60		var req declineRequest
 61		if r.ContentLength != 0 {
 62			if err := decodeJSON(r, &req); err != nil {
 63				writeError(w, err)
 64				return
 65			}
 66		}
 67		s.respondPayment(w, func() (payment.Payment, error) {
 68			return s.svc.Decline(r.Context(), r.PathValue("id"), req.Reason)
 69		})
 70	}
 71	
 72	func (s *Server) refundPayment(w http.ResponseWriter, r *http.Request) {
 73		id := r.PathValue("id")
 74		fp, err := bodyFingerprint(r)
 75		if err != nil {
 76			writeError(w, err)
 77			return
 78		}
 79		var req refundRequest
 80		if err := decodeJSON(r, &req); err != nil {
 81			writeError(w, err)
 82			return
 83		}
 84		p, err := s.svc.Get(r.Context(), id)
 85		if err != nil {
 86			writeError(w, err)
 87			return
 88		}
 89		amount, err := money.Parse(req.Amount, p.Amount.Currency.Code)
 90		if err != nil {
 91			writeError(w, fmt.Errorf("amount: %w", err))
 92			return
 93		}
 94		s.idempotent(w, r, fp, func() (int, any) {
 95			p, _, err := s.svc.Refund(r.Context(), id, amount)
 96			if err != nil {
 97				return errorResponse(err)
 98			}
 99			return http.StatusCreated, toPaymentResponse(p)
100		})
101	}
102	
103	func (s *Server) listPayments(w http.ResponseWriter, r *http.Request) {
104		q := r.URL.Query()
105		page := payment.Page{Cursor: q.Get("cursor")}
106		if v := q.Get("limit"); v != "" {
107			n, err := strconv.Atoi(v)
108			if err != nil {
109				writeError(w, fmt.Errorf("%w: limit %q is not a number", payment.ErrInvalidInput, v))
110				return
111			}
112			page.Limit = n
113		}
114		ps, next, err := s.svc.List(r.Context(), r.PathValue("merchantID"), page)
115		if err != nil {
116			writeError(w, err)
117			return
118		}
119		out := listResponse{Data: make([]paymentResponse, 0, len(ps)), NextCursor: next}
120		for _, p := range ps {
121			out.Data = append(out.Data, toPaymentResponse(p))
122		}
123		writeJSON(w, http.StatusOK, out)
124	}
125	
126	func (s *Server) listDeadLetters(w http.ResponseWriter, _ *http.Request) {
127		dead := s.hooks.DeadLetters()
128		out := make([]deadLetterResponse, 0, len(dead))
129		for _, d := range dead {
130			out = append(out, toDeadLetterResponse(d))
131		}
132		writeJSON(w, http.StatusOK, map[string]any{"data": out})
133	}
134	
135	func (s *Server) respondPayment(w http.ResponseWriter, op func() (payment.Payment, error)) {
136		p, err := op()
137		if err != nil {
138			writeError(w, err)
139			return
140		}
141		writeJSON(w, http.StatusOK, toPaymentResponse(p))
142	}
143	
144	func decodeJSON(r *http.Request, dst any) error {
145		dec := json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes))
146		dec.DisallowUnknownFields()
147		if err := dec.Decode(dst); err != nil {
148			return fmt.Errorf("%w: malformed JSON body: %v", payment.ErrInvalidInput, err)
149		}
150		return nil
151	}
152	
153	func writeJSON(w http.ResponseWriter, status int, body any) {
154		w.Header().Set("Content-Type", "application/json")
155		w.WriteHeader(status)
156		_ = json.NewEncoder(w).Encode(body)
157	}

