// bodyFingerprint hashes the request path and raw body, then restores the
// body so the handler can decode it.
func bodyFingerprint(r *http.Request) (string, error) {
	raw, err := io.ReadAll(io.LimitReader(r.Body, maxBodyBytes))
	if err != nil {
		return "", fmt.Errorf("%w: read body: %v", payment.ErrInvalidInput, err)
	}
	r.Body = io.NopCloser(bytes.NewReader(raw))
	return hash(r.URL.Path + "|" + string(raw)), nil
}

func hash(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

args.new:
// requestFingerprint hashes the HTTP method, path and canonicalized request
// payload so semantically identical retries share a fingerprint regardless of
// JSON formatting, field order, currency case or trailing zeros in amounts.
func requestFingerprint(method, path string, canonical any) string {
	raw, err := json.Marshal(struct {
		Method string `json:"m"`
		Path   string `json:"p"`
		Body   any    `json:"b"`
	}{
		Method: method,
		Path:   path,
		Body:   canonical,
	})
	if err != nil {
		panic(fmt.Sprintf("marshal fingerprint: %v", err))
	}
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

