func TestIdempotentCreateSemanticEquivalence(t *testing.T) {
	a := newTestAPI(t)
	first := a.do("POST", "/payments", `{"merchant_id":"m_310","amount":"10.50","currency":"USD"}`, IdempotencyKeyHeader, "sdk-1")
	if first.Code != http.StatusCreated {
		t.Fatalf("first status %d: %s", first.Code, first.Body)
	}
	retries := []string{
		`{"currency": "usd", "amount": "10.5", "merchant_id": "m_310"}`,
		"{\n\t\"amount\": \"010.50\",\n\t\"merchant_id\": \"m_310\",\n\t\"currency\": \"Usd\"\n}",
		`{"merchant_id":"m_\u003310","amount":" 10.5 ","currency":" usd "}`,
	}
	for _, body := range retries {
		retry := a.do("POST", "/payments", body, IdempotencyKeyHeader, "sdk-1")
		if retry.Code != http.StatusCreated {
			t.Fatalf("retry %q status %d: %s", body, retry.Code, retry.Body)
		}
		if retry.Header().Get(ReplayedHeader) != "true" || retry.Body.String() != first.Body.String() {
			t.Fatalf("retry %q not replayed: %s vs %s", body, retry.Body, first.Body)
		}
	}

	conflicts := []string{
		`{"merchant_id":"m_311","amount":"10.50","currency":"USD"}`,
		`{"merchant_id":"M_310","amount":"10.50","currency":"USD"}`,
		`{"merchant_id":"m_310","amount":"10.51","currency":"USD"}`,
		`{"merchant_id":"m_310","amount":"10.50","currency":"EUR"}`,
	}
	for _, body := range conflicts {
		conflict := a.do("POST", "/payments", body, IdempotencyKeyHeader, "sdk-1")
		if conflict.Code != http.StatusUnprocessableEntity {
			t.Fatalf("conflict %q status %d: %s", body, conflict.Code, conflict.Body)
		}
		if e := decode[errorBody](t, conflict); e.Error.Code != "idempotency_key_reused" {
			t.Fatalf("conflict %q code %q", body, e.Error.Code)
		}
	}

	list := decode[listResponse](t, a.do("GET", "/merchants/m_310/payments", ""))
	if len(list.Data) != 1 {
		t.Fatalf("expected 1 payment, got %d", len(list.Data))
	}
}

func TestIdempotentRefundSemanticEquivalence(t *testing.T) {
	a := newTestAPI(t)
	p := a.createSucceeded("10.00", "USD")

	first := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"5.00"}`, IdempotencyKeyHeader, "ref-1")
	if first.Code != http.StatusCreated {
		t.Fatalf("first refund %d: %s", first.Code, first.Body)
	}
	for _, body := range []string{`{"amount": "5"}`, `{"amount": "5.0"}`, `{"amount": "05.00"}`} {
		retry := a.do("POST", "/payments/"+p.ID+"/refunds", body, IdempotencyKeyHeader, "ref-1")
		if retry.Code != http.StatusCreated || retry.Header().Get(ReplayedHeader) != "true" || retry.Body.String() != first.Body.String() {
			t.Fatalf("retry %q: status=%d replayed=%q body=%s", body, retry.Code, retry.Header().Get(ReplayedHeader), retry.Body)
		}
	}

	conflict := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount": "6"}`, IdempotencyKeyHeader, "ref-1")
	if conflict.Code != http.StatusUnprocessableEntity {
		t.Fatalf("conflict status %d: %s", conflict.Code, conflict.Body)
	}
	if e := decode[errorBody](t, conflict); e.Error.Code != "idempotency_key_reused" {
		t.Fatalf("conflict code %q", e.Error.Code)
	}

	// Full remaining refund transitions payment to REFUNDED; retry must still replay 201.
	full := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"5.00"}`, IdempotencyKeyHeader, "ref-2")
	if full.Code != http.StatusCreated {
		t.Fatalf("full refund %d: %s", full.Code, full.Body)
	}
	fullRetry := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount": "5"}`, IdempotencyKeyHeader, "ref-2")
	if fullRetry.Code != http.StatusCreated || fullRetry.Header().Get(ReplayedHeader) != "true" || fullRetry.Body.String() != full.Body.String() {
		t.Fatalf("full refund retry: status=%d replayed=%q body=%s", fullRetry.Code, fullRetry.Header().Get(ReplayedHeader), fullRetry.Body)
	}

	got := decode[paymentResponse](t, a.do("GET", "/payments/"+p.ID, ""))
	if got.Status != "REFUNDED" || len(got.Refunds) != 2 || got.RefundedAmount != "10.00" {
		t.Fatalf("unexpected final payment %+v", got)
	}
}

